begin;
alter table public.profiles add column if not exists game_ids jsonb not null default '{}'::jsonb;
alter table public.profiles add column if not exists last_seen timestamptz;
create or replace function public.squad_heartbeat() returns void language sql security definer set search_path=public as $$ update public.profiles set last_seen=now() where id=auth.uid(); $$;
revoke all on function public.squad_heartbeat() from public; grant execute on function public.squad_heartbeat() to authenticated;
create or replace function public.squad_is_blocked(a uuid,b uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.squad_user_blocks where (user_id=a and blocked_user_id=b) or (user_id=b and blocked_user_id=a)); $$;
revoke all on function public.squad_is_blocked(uuid,uuid) from public;grant execute on function public.squad_is_blocked(uuid,uuid) to authenticated;
drop policy if exists "Users can send direct messages as themselves" on public.direct_messages;
create policy "Users can send direct messages as themselves" on public.direct_messages for insert to authenticated with check(sender_id=auth.uid() and recipient_id<>auth.uid() and not public.squad_is_blocked(sender_id,recipient_id));
create table if not exists public.squad_friendships(sender_id uuid references public.profiles(id) on delete cascade,recipient_id uuid references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted')),created_at timestamptz not null default now(),primary key(sender_id,recipient_id),check(sender_id<>recipient_id));
create unique index if not exists squad_friend_pair on public.squad_friendships(least(sender_id,recipient_id),greatest(sender_id,recipient_id));
alter table public.squad_friendships enable row level security;
grant select on public.squad_friendships to authenticated;
drop policy if exists "Friends view own edges" on public.squad_friendships;
create policy "Friends view own edges" on public.squad_friendships for select to authenticated using(auth.uid() in(sender_id,recipient_id));
create or replace function public.squad_friend_action(peer uuid,action text) returns void language plpgsql security definer set search_path=public as $$
begin
 if auth.uid() is null or peer=auth.uid() then raise exception 'Sign in and choose another player'; end if;
 if action='request' then
  if public.squad_is_blocked(auth.uid(),peer) then raise exception 'Friend request unavailable'; end if;
  insert into public.squad_friendships(sender_id,recipient_id) values(auth.uid(),peer) on conflict do nothing;
 elsif action='accept' then update public.squad_friendships set status='accepted' where sender_id=peer and recipient_id=auth.uid() and status='pending';
 elsif action='remove' then delete from public.squad_friendships where (sender_id=peer and recipient_id=auth.uid()) or(sender_id=auth.uid() and recipient_id=peer);
 else raise exception 'Unknown action'; end if;
end; $$;
revoke all on function public.squad_friend_action(uuid,text) from public;grant execute on function public.squad_friend_action(uuid,text) to authenticated;
create table if not exists public.squad_typing(sender_id uuid references public.profiles(id) on delete cascade,recipient_id uuid references public.profiles(id) on delete cascade,expires_at timestamptz not null,primary key(sender_id,recipient_id),check(sender_id<>recipient_id));
alter table public.squad_typing enable row level security;grant select on public.squad_typing to authenticated;
drop policy if exists "Typing participants" on public.squad_typing;
create policy "Typing participants" on public.squad_typing for select to authenticated using(auth.uid() in(sender_id,recipient_id) and not public.squad_is_blocked(sender_id,recipient_id));
create or replace function public.squad_set_typing(peer uuid,active boolean) returns void language plpgsql security definer set search_path=public as $$
begin
 if auth.uid() is null or peer=auth.uid() or public.squad_is_blocked(auth.uid(),peer) then return; end if;
 insert into public.squad_typing values(auth.uid(),peer,now()+case when active then interval '5 seconds' else interval '0 seconds' end) on conflict(sender_id,recipient_id) do update set expires_at=excluded.expires_at;
end; $$;
revoke all on function public.squad_set_typing(uuid,boolean) from public;grant execute on function public.squad_set_typing(uuid,boolean) to authenticated;
create table if not exists public.squad_chat_reports(id bigint generated by default as identity primary key,reporter_id uuid not null references auth.users(id) on delete cascade,reported_user_id uuid not null references auth.users(id) on delete cascade,reason text not null check(char_length(reason) between 5 and 500),created_at timestamptz not null default now(),check(reporter_id<>reported_user_id));
alter table public.squad_chat_reports enable row level security;grant insert on public.squad_chat_reports to authenticated;grant usage on sequence public.squad_chat_reports_id_seq to authenticated;
drop policy if exists "Report chat as yourself" on public.squad_chat_reports;
create policy "Report chat as yourself" on public.squad_chat_reports for insert to authenticated with check(reporter_id=auth.uid());
do $$ begin
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='squad_friendships') then alter publication supabase_realtime add table public.squad_friendships; end if;
 if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='squad_typing') then alter publication supabase_realtime add table public.squad_typing; end if;
end $$;
commit;
